"use strict";(globalThis.webpackChunkmy_website||=[]).push([[64125],{42616(e){e.exports=JSON.parse('{"slug":"active-slot-coefficient","title":"Active Slot Coefficient","short":"The protocol parameter that controls the probability a slot is assigned an elected block-producer. On mainnet it is currently 0.05.","category":"consensus","aliases":["f parameter","f"],"mentalModel":null,"related":["slot","block","ouroboros","k-parameter"],"sources":[],"link":null,"level":"advanced","body":"A protocol parameter, written `f`, that sets the average fraction of slots in which a stake-pool wins the leader election and is allowed to produce a block. Cardano mainnet currently runs with `f = 0.05`, which combined with one-second slots works out to about one block every 20 seconds on average.\\n\\nTuning `f` is a trade-off: a higher value gives more blocks per minute but increases the chance of short forks when two pools happen to win the same slot; a lower value reduces fork risk but slows block production."}')}}]);